changeSet.sql:
DO $$ BEGIN IF EXISTS (SELECT 1 FROM
			pg_constraint WHERE conname = 'fk_favorite_provider_user' AND
			conrelid = 't_favorite_provider'::regclass) THEN ALTER TABLE
			public.t_favorite_provider DROP CONSTRAINT fk_favorite_provider_user;
			END IF; END $$;

UPDATE public.t_service_provider sp SET c_user_id = u.c_identity_id FROM public.t_user u WHERE sp.c_user_id = u.c_id AND sp.c_user_id != u.c_identity_id;
UPDATE public.t_service_provider sp SET c_approved_by = u.c_identity_id FROM public.t_user u WHERE sp.c_approved_by = u.c_id AND sp.c_approved_by != u.c_identity_id;
UPDATE public.t_service_provider sp SET c_rejected_by = u.c_identity_id FROM public.t_user u WHERE sp.c_rejected_by = u.c_id AND sp.c_rejected_by != u.c_identity_id;
UPDATE public.t_provider_client pc SET c_user_id = u.c_identity_id FROM public.t_user u WHERE pc.c_user_id = u.c_id AND pc.c_user_id != u.c_identity_id;
UPDATE public.t_favorite_provider fp SET c_user_id = u.c_identity_id FROM public.t_user u WHERE fp.c_user_id = u.c_id AND fp.c_user_id != u.c_identity_id;
DELETE FROM public.t_service_provider sp WHERE NOT EXISTS ( SELECT 1 FROM public.t_user u WHERE u.c_identity_id = sp.c_user_id ); DELETE FROM public.t_provider_client pc WHERE NOT EXISTS ( SELECT 1 FROM public.t_user u WHERE u.c_identity_id = pc.c_user_id ); DELETE FROM public.t_favorite_provider fp WHERE NOT EXISTS ( SELECT 1 FROM public.t_user u WHERE u.c_identity_id = fp.c_user_id );
